      + (destacarCPF ? 'setTimeout(function(){var c=document.getElementById("mc-cpf");if(c)c.focus();},100);' : '')
      + '},200);<' + '/script>'
      + '<button class="st-btn st-btn-danger" onclick="doLogout();fecharTela();">Sair da conta</button>';
    abrirTela('Minha Conta', html);
