  if (_sessao?.lat && _sessao?.lng) _perfAtualizarMapa(_sessao.lat, _sessao.lng, [end.rua, end.numero, end.cidade].filter(Boolean).join(', '));
  renderServicos();

  // Buscar dados atualizados do servidor
