// ─── Upload de logo para postos do mapa (google-*, osm-*, anp-*) ─────────────
var _logoBandPostoId = null;
var _logoBandFile = null;

function abrirUploadLogoPostoBand(postoId, nome) {
  _logoBandPostoId = postoId;
  _logoBandFile = null;
  document.getElementById('logo-band-nome').textContent = nome || postoId;
  // Resetar UI
  var inp = document.getElementById('logo-band-input');
  if (inp) inp.value = '';
  var st = document.getElementById('logo-band-status');
  if (st) { st.style.display='none'; st.textContent=''; }
  var btn = document.getElementById('logo-band-btn-enviar');
  if (btn) { btn.disabled=true; btn.style.opacity='0.4'; }
  var img = document.getElementById('logo-band-preview-img');
  var wrap = document.getElementById('logo-band-preview-wrap');
  if (img) { img.src=''; img.style.display='none'; }
  if (wrap) wrap.style.fontSize='28px';
  document.getElementById('modal-logo-posto-band').style.display='flex';
}

function fecharModalLogoBand() {
  document.getElementById('modal-logo-posto-band').style.display='none';
  _logoBandPostoId = null;
  _logoBandFile = null;
}

function logoHandleChange(inp) {
  var f = inp.files && inp.files[0];
  if (!f) return;
  var st = document.getElementById('logo-band-status');
  if (f.size > 3 * 1024 * 1024) {
    if (st) { st.textContent='⚠️ Imagem muito grande (máx. 3 MB).'; st.style.color='#FF5252'; st.style.display='block'; }
    return;
  }
  _logoBandFile = f;
  var reader = new FileReader();
  reader.onload = function(e) {
    var img = document.getElementById('logo-band-preview-img');
    var wrap = document.getElementById('logo-band-preview-wrap');
    if (img) { img.src = e.target.result; img.style.display='block'; }
    if (wrap) wrap.style.fontSize='0';
  };
  reader.readAsDataURL(f);
  if (st) { st.textContent='📸 ' + f.name + ' — clique em "Enviar Logo".'; st.style.color='rgba(255,255,255,0.5)'; st.style.display='block'; }
  var btn = document.getElementById('logo-band-btn-enviar');
  if (btn) { btn.disabled=false; btn.style.opacity='1'; }
}

async function enviarLogoBand() {
  if (!_logoBandFile || !_logoBandPostoId) return;
  var st  = document.getElementById('logo-band-status');
  var btn = document.getElementById('logo-band-btn-enviar');
  if (btn) { btn.disabled=true; btn.innerHTML='<i class="fas fa-spinner fa-spin"></i> Enviando...'; }
  if (st)  { st.textContent='⏳ Enviando logo...'; st.style.color='rgba(255,255,255,0.5)'; st.style.display='block'; }
  try {
    var form = new FormData();
    form.append('logo', _logoBandFile);
    form.append('postoId', _logoBandPostoId);
    var r = await fetch('/api/admin/posto-band/logo?key=' + encodeURIComponent(ADMIN_KEY), {
      method: 'POST', body: form
    });
    var d = await r.json();
    if (!r.ok || !d.ok) throw new Error(d.erro || 'Erro ao enviar');
    if (st) { st.textContent='✅ Logo salvo! Já aparece no mapa e lista.'; st.style.color='#00C853'; }
    showToast('✅ Logo do posto salvo com sucesso!', 'ok');
    var logoFinal = d.logoUrl + '?t=' + Date.now();
    // Atualizar preview no modal
    var img = document.getElementById('logo-band-preview-img');
    if (img) { img.src = logoFinal; img.style.display='block'; }
    _logoBandFile = null;
    var inp = document.getElementById('logo-band-input');
    if (inp) inp.value = '';
    // Atualizar célula da tabela imediatamente (sem recarregar toda a lista)
    // A tabela tem células na coluna 0 de cada linha com data-posto-id
    var rows = document.querySelectorAll('#postos-tbody tr');
    rows.forEach(function(row) {
      var btn = row.querySelector('button[onclick*="' + _logoBandPostoId + '"]');
      if (btn) {
        var cell = row.querySelector('td:first-child');
        if (cell) {
          var _img = document.createElement('img');
          _img.src = logoFinal;
          _img.style.cssText = 'width:32px;height:32px;object-fit:contain;border-radius:6px;background:#fff;padding:2px';
          _img.onerror = function(){ this.style.display='none'; };
          cell.innerHTML = '';
          cell.appendChild(_img);
        }
      }
    });
    // Fechar modal após 1.5s e recarregar lista
    setTimeout(function() {
      fecharModalLogoBand();
      carregarPostos();
    }, 1500);
  } catch(e) {
    if (st) { st.textContent='❌ ' + (e.message||e); st.style.color='#FF5252'; }
    showToast('❌ Erro ao enviar logo: ' + (e.message||e), 'err');
  } finally {
    if (btn) { btn.disabled=false; btn.style.opacity='1'; btn.innerHTML='<i class="fas fa-cloud-upload-alt"></i> Enviar Logo'; }
  }
}

// ─── Toggle ativar/desativar posto direto na tabela ───────────────────────────
async function toggleStatusParceiro(el) {
  const id = el.dataset.pid;
  const statusAtual = el.dataset.status || 'ativo';
  const novoStatus = statusAtual === 'ativo' ? 'inativo' : 'ativo';
  const isAtivo = novoStatus === 'ativo';
  // Feedback visual imediato (spinner enquanto salva)
  const htmlOriginal = el.innerHTML;
  el.innerHTML = '<i class="fas fa-spinner fa-spin" style="margin-right:4px"></i>...';
  el.style.pointerEvents = 'none';
  try {
    const res = await fetch('/api/admin/parceiros/' + encodeURIComponent(id) + '?key=' + encodeURIComponent(ADMIN_KEY), {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: novoStatus })
    });
    const d = await res.json();
    if (!res.ok || d.erro) throw new Error(d.erro || 'Erro ao salvar');
    // Atualiza visual inline
    el.dataset.status = novoStatus;
    el.style.background = isAtivo ? 'rgba(105,240,174,0.15)' : 'rgba(255,82,82,0.12)';
    el.style.color = isAtivo ? '#69F0AE' : '#FF5252';
    el.style.border = isAtivo ? '1px solid rgba(105,240,174,0.3)' : '1px solid rgba(255,82,82,0.25)';
    el.innerHTML = '<i class="fas ' + (isAtivo ? 'fa-toggle-on' : 'fa-toggle-off') + '" style="margin-right:4px"></i>' + (isAtivo ? 'Ativo' : 'Inativo');
    // Atualiza _parceiros em memória
    const p = _parceiros.find(x => x.id === id);
    if (p) p.status = novoStatus;
    showToast(isAtivo ? '✅ Posto ativado!' : '⚠️ Posto desativado!', isAtivo ? 'ok' : '');
  } catch(e) {
    // Restaura visual original em caso de erro
    el.innerHTML = htmlOriginal;
    showToast('❌ Erro: ' + e.message, 'err');
  } finally {
    el.style.pointerEvents = '';
  }
}

// ─── Modal Editar Parceiro ────────────────────────────────────────────────────
let _parceiroEditandoId = null;
let _postoVeioDaANP = false; // flag: posto foi selecionado via "Usar dados" na seção ANP

// Popula o select de planos do modal de posto com os planos B2B de postos
async function popularSelectPlanosModal(planoAtual) {
  const sel = document.getElementById('ep-plano');
  if (!sel) return;
  // Usa _planosData (planos de postos) — carrega da rota planos-posto se vazio
  let planos = _planosData || [];
  if (!planos.length) {
    try {
      const r = await fetch('/api/admin/planos-posto?key=' + encodeURIComponent(ADMIN_KEY));
      const d = await r.json();
      planos = d.planos || [];
      _planosData = planos;
    } catch {}
  }
  if (!planos.length) {
    // Fallback estático
    sel.innerHTML = '<option value="visibilidade">Visibilidade (Grátis)</option>'
      + '<option value="basico">Básico</option>'
      + '<option value="premium">Premium</option>'
      + '<option value="pro">Pro</option>';
  } else {
    sel.innerHTML = planos.filter(p => p.ativo !== false).map(p => {
      const valorFmt = p.valor === 0 ? 'Grátis' : 'R$ ' + (p.valor / 100).toFixed(2).replace('.',',') + '/' + (p.ciclo === 'monthly' ? 'mês' : p.ciclo === 'yearly' ? 'ano' : p.ciclo === 'trial' ? 'teste' : '∞');
      return '<option value="' + p.id + '">' + (p.emoji || '') + ' ' + p.nome + ' — ' + valorFmt + '</option>';
    }).join('');
  }
  if (planoAtual) sel.value = planoAtual;
  if (!sel.value && sel.options.length) sel.value = sel.options[0].value;
  // Atualiza preview logo após popular
  epAtualizarPreviewPlano();
}

// Atualiza o preview visual de benefícios ao trocar o plano no modal do posto
function epAtualizarPreviewPlano() {
  const sel     = document.getElementById('ep-plano');
  const preview = document.getElementById('ep-plano-preview');
  const vazio   = document.getElementById('ep-plano-vazio');
  if (!sel || !preview || !vazio) return;

  const planoId = sel.value;
  const plano   = (_planosData || []).find(x => x.id === planoId);

  if (!plano) {
    preview.style.display = 'none';
    vazio.style.display   = 'block';
    return;
  }

  vazio.style.display   = 'none';
  preview.style.display = 'block';

  const cor        = plano.cor || '#FF6D00';
  const beneficios = Array.isArray(plano.beneficios) ? plano.beneficios : [];
  const features   = Array.isArray(plano.features)   ? plano.features   : [];
  const valorFmt   = plano.valor === 0 ? 'Grátis' : 'R$ ' + (plano.valor / 100).toFixed(2).replace('.', ',');
  const cicloLabel = { forever:'para sempre', monthly:'/mês', yearly:'/ano', trial:'período de teste' };
  const cicloFmt   = cicloLabel[plano.ciclo] || plano.ciclo;

  // Badge de período
  let periodoBadge = '';
  if (plano.ciclo === 'trial' && plano.diasTeste > 0) {
    periodoBadge = '<span style="background:rgba(255,214,0,0.15);color:#FFD600;border:1px solid rgba(255,214,0,0.3);border-radius:100px;padding:2px 10px;font-size:10px;font-weight:800">⏱️ ' + plano.diasTeste + ' dias de teste</span>';
  } else if (plano.ciclo === 'forever') {
    periodoBadge = '<span style="background:rgba(0,200,83,0.12);color:#00C853;border:1px solid rgba(0,200,83,0.25);border-radius:100px;padding:2px 10px;font-size:10px;font-weight:800">♾️ Para sempre</span>';
  } else if (plano.valor > 0) {
    periodoBadge = '<span style="background:rgba(66,165,245,0.1);color:#42A5F5;border:1px solid rgba(66,165,245,0.2);border-radius:100px;padding:2px 10px;font-size:10px;font-weight:800">💳 ' + cicloFmt + '</span>';
  }

  // Benefícios fixos do plano
  const bAtivos = BENEFICIOS_POSTO.filter(b => beneficios.includes(b.id));
  const bHTML = bAtivos.length > 0
    ? bAtivos.map(b =>
        '<div style="display:flex;align-items:center;gap:8px;font-size:11px;color:rgba(255,255,255,0.8)">'
        + '<i class="' + b.icon + '" style="color:' + cor + ';width:14px;text-align:center;font-size:11px;flex-shrink:0"></i>'
        + '<span>' + b.label + '</span>'
        + '</div>'
      ).join('')
    : '';

  // Features extras (legado)
  const fAtivos = features.filter(f => f.incluido);
  const fHTML = fAtivos.length > 0
    ? fAtivos.map(f =>
        '<div style="display:flex;align-items:center;gap:8px;font-size:11px;color:rgba(255,255,255,0.65)">'
        + '<i class="fas fa-check" style="color:' + cor + ';width:14px;text-align:center;font-size:10px;flex-shrink:0"></i>'
        + '<span>' + f.texto + '</span>'
        + '</div>'
      ).join('')
    : '';

  const totalBeneficios = bAtivos.length + fAtivos.length;

  preview.innerHTML =
    // Cabeçalho do plano
    '<div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:12px">'
    + '<div style="display:flex;align-items:center;gap:10px">'
    +   '<div style="font-size:28px;line-height:1">' + (plano.emoji || '📦') + '</div>'
    +   '<div>'
    +     '<div style="font-size:14px;font-weight:900;color:#fff">' + plano.nome + '</div>'
    +     '<div style="font-size:18px;font-weight:900;color:' + cor + ';line-height:1.2">' + valorFmt
    +       (plano.valor > 0 ? '<span style="font-size:11px;color:rgba(255,255,255,0.35)"> ' + cicloFmt + '</span>' : '')
    +     '</div>'
    +   '</div>'
    + '</div>'
    + periodoBadge
    + '</div>'
    // Benefícios
    + (totalBeneficios > 0
      ? '<div style="background:rgba(0,0,0,0.2);border-radius:10px;padding:12px">'
        + '<div style="font-size:10px;font-weight:800;color:rgba(255,255,255,0.4);text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px">Benefícios incluídos</div>'
        + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">' + bHTML + fHTML + '</div>'
        + '</div>'
      : '<div style="color:rgba(255,255,255,0.25);font-size:11px;font-style:italic;text-align:center;padding:8px">Nenhum benefício configurado neste plano</div>'
    )
    ;
}

