    var credLabel = it.id === 'woovi' ? 'cred-status-woovi' : it.id === 'mercadopago' ? 'cred-status-mp' : 'cred-status-pb';
    var diagKey2 = it.id === 'mercadopago' ? 'mp' : it.id;
