// renderizarPlanosGrid substituída por renderizarAbasPlanos + renderizarPlanoSelecionado

// Atualiza visibilidade da caixa de dias de teste ao mudar o ciclo
function ppToggleTrialBox(i) {
  const ciclo = document.getElementById('pp-ciclo-' + i);
  const box   = document.getElementById('pp-trial-box-' + i);
  if (!ciclo || !box) return;
  box.style.display = ['trial','forever'].includes(ciclo.value) ? 'flex' : 'none';
  const valorEl = document.getElementById('pp-valor-' + i);
  if (valorEl) {
    const isFree = ciclo.value === 'forever';
    valorEl.disabled = isFree;
    valorEl.style.opacity = isFree ? '0.35' : '1';
    valorEl.style.cursor  = isFree ? 'not-allowed' : 'text';
  }
}

// Toggle benefício no array em memória E atualiza borda do label
function toggleBeneficioPostoCard(planoIdx, bid, checked, inputEl) {
  if (!_planosData[planoIdx]) return;
  if (!Array.isArray(_planosData[planoIdx].beneficios)) _planosData[planoIdx].beneficios = [];
  if (checked) {
    if (!_planosData[planoIdx].beneficios.includes(bid)) _planosData[planoIdx].beneficios.push(bid);
  } else {
    _planosData[planoIdx].beneficios = _planosData[planoIdx].beneficios.filter(b => b !== bid);
  }
  // Atualiza borda do label
  const label = inputEl ? inputEl.closest('label') : null;
  if (label) {
    const cor = (document.getElementById('pp-cor-' + planoIdx) || {value:'#FF6D00'}).value;
    label.style.borderColor = checked ? cor + '55' : 'rgba(255,255,255,0.07)';
  }
}

// Salvar plano de posto inline (PUT)
async function salvarPlanoPostoInline(idx, id) {
  const nome  = (document.getElementById('pp-nome-' + idx)||{value:''}).value.trim();
  if (!nome) { alert('Informe o nome do plano.'); return; }
  const ciclo = (document.getElementById('pp-ciclo-' + idx)||{value:'monthly'}).value;
  const body = {
    nome,
    emoji:     (document.getElementById('pp-emoji-' + idx)||{value:'📦'}).value.trim() || '📦',
    cor:       (document.getElementById('pp-cor-' + idx)||{value:'#FF6D00'}).value,
    valor:     parseInt((document.getElementById('pp-valor-' + idx)||{value:'0'}).value) || 0,
    ciclo,
    descricao: (document.getElementById('pp-desc-' + idx)||{value:''}).value.trim(),
    ativo:     (document.getElementById('pp-ativo-' + idx)||{checked:true}).checked,
    destaque:  (document.getElementById('pp-destaque-' + idx)||{checked:false}).checked,
    diasTeste: (['trial','forever'].includes(ciclo)) ? parseInt((document.getElementById('pp-dias-' + idx)||{value:'0'}).value)||0 : 0,
    beneficios: _planosData[idx] ? (_planosData[idx].beneficios || []) : []
  };
  try {
    const res = await fetch('/api/admin/planos-posto/' + encodeURIComponent(id) + '?key=' + encodeURIComponent(ADMIN_KEY), {
      method: 'PUT', headers: {'Content-Type':'application/json'}, body: JSON.stringify(body)
    });
    const data = await res.json();
    if (data.ok) {
      mostrarToastPostos('✅ Plano "' + nome + '" salvo!', '#00C853');
      await carregarEstatisticasPlanos();
    } else {
      mostrarToastPostos('❌ Erro: ' + (data.erro||'Falha ao salvar'), '#FF5252');
    }
  } catch(e) { mostrarToastPostos('❌ Erro: ' + e.message, '#FF5252'); }
}

// Excluir plano de posto inline
async function deletarPlanoPostoInline(id) {
  if (!confirm('Excluir o plano "' + id + '"? Esta ação não pode ser desfeita.')) return;
  try {
    const res = await fetch('/api/admin/planos-posto/' + encodeURIComponent(id) + '?key=' + encodeURIComponent(ADMIN_KEY), { method: 'DELETE' });
    const data = await res.json();
    if (data.ok) {
      mostrarToastPostos('🗑️ Plano excluído.', '#FF6D00');
      await carregarEstatisticasPlanos();
    } else {
      mostrarToastPostos('❌ Erro: ' + (data.erro||'Falha'), '#FF5252');
    }
  } catch(e) { mostrarToastPostos('❌ ' + e.message, '#FF5252'); }
}

function mostrarToastPostos(msg, cor) {
  const t = document.getElementById('planos-posto-toast');
  if (!t) return;
  t.textContent = msg;
  t.style.background = cor || '#00C853';
  t.style.display = 'block';
  t.style.opacity = '1';
  setTimeout(() => { t.style.opacity = '0'; setTimeout(() => { t.style.display = 'none'; t.style.opacity = '1'; }, 400); }, 3000);
}

function renderizarBeneficiosModal(selecionados = []) {
  const grid = document.getElementById('mp-beneficios-grid');
  if (!grid) return;
  grid.innerHTML = BENEFICIOS_POSTO.map(b => {
    var checked = selecionados.includes(b.id);
    var borderCol = checked ? 'rgba(255,109,0,0.35)' : 'rgba(255,255,255,0.08)';
    return '<label class="benef-label" style="display:flex;align-items:center;gap:8px;background:rgba(255,255,255,0.04);border:1.5px solid ' + borderCol + ';border-radius:9px;padding:9px 12px;cursor:pointer;transition:.15s">'
      + '<input type="checkbox" data-bid="' + b.id + '" class="beneficio-check" style="accent-color:var(--laranja);width:15px;height:15px;flex-shrink:0" '
      + (checked ? 'checked' : '')
      + ' onchange="mpBenefCheck(this)"/>'
      + '<i class="' + b.icon + '" style="color:rgba(255,255,255,0.4);font-size:11px;flex-shrink:0"></i>'
      + '<span style="font-size:11px;color:rgba(255,255,255,0.75)">' + b.label + '</span>'
      + '</label>';
  }).join('');
}

function mpBenefCheck(el) {
  var label = el.closest('label');
  if (label) label.style.borderColor = el.checked ? 'rgba(255,109,0,0.35)' : 'rgba(255,255,255,0.08)';
}

function coletarBeneficiosModal() {
  return Array.from(document.querySelectorAll('#mp-beneficios-grid .beneficio-check'))
    .filter(el => el.checked)
    .map(el => el.dataset.bid);
}

function mpAtualizarPeriodo() {
  const ciclo = document.getElementById('mp-ciclo').value;
  const box   = document.getElementById('mp-trial-box');
  if (ciclo === 'trial' || ciclo === 'forever') {
    box.style.display = 'block';
    if (ciclo === 'forever') document.getElementById('mp-dias-teste').value = '0';
  } else {
    box.style.display = 'none';
  }
}

// ─── Modal: abrir para editar plano existente ────────────────────────────────
function abrirModalEditarPlano(id) {
  const p = _planosData.find(x => x.id === id);
  if (!p) return;
  _planoEditandoId = id;
  document.getElementById('modal-plano-titulo').textContent = '✏️ Editar Plano — ' + p.nome;
  document.getElementById('mp-emoji').value     = p.emoji || '📦';
  document.getElementById('mp-nome').value      = p.nome || '';
  document.getElementById('mp-valor').value     = p.valor ? (p.valor / 100).toFixed(2) : '0';
  document.getElementById('mp-ciclo').value     = p.ciclo || 'monthly';
  document.getElementById('mp-cor').value       = p.cor || '#FF6D00';
  document.getElementById('mp-descricao').value = p.descricao || '';
  document.getElementById('mp-ativo').checked   = !!p.ativo;
  document.getElementById('mp-destaque').checked = !!p.destaque;
  if (document.getElementById('mp-dias-teste')) document.getElementById('mp-dias-teste').value = p.diasTeste || 30;
  const btnDel = document.getElementById('mp-deletar-btn');
  btnDel.style.display = ['posto_gratis','posto_basico','posto_plus','free','premium','anual'].includes(id) ? 'none' : 'inline-flex';
  renderizarBeneficiosModal(p.beneficios || []);
  renderizarFeaturesModal(p.features || []);
  mpAtualizarPeriodo();
  document.getElementById('modal-plano').style.display = 'block';
}

// ─── Modal: abrir para criar novo plano ─────────────────────────────────────
function abrirModalNovoPlano() { abrirModalNovoPLano(); }
function abrirModalNovoPLano() {
  _planoEditandoId = null;
  document.getElementById('modal-plano-titulo').textContent = '➕ Novo Plano para Postos';
  document.getElementById('mp-emoji').value     = '⭐';
  document.getElementById('mp-nome').value      = '';
  document.getElementById('mp-valor').value     = '0';
  document.getElementById('mp-ciclo').value     = 'trial';
  document.getElementById('mp-cor').value       = '#FF6D00';
  document.getElementById('mp-descricao').value = '';
  document.getElementById('mp-ativo').checked    = true;
  document.getElementById('mp-destaque').checked = false;
  document.getElementById('mp-deletar-btn').style.display = 'none';
  if (document.getElementById('mp-dias-teste')) document.getElementById('mp-dias-teste').value = 30;
  // Benefícios padrão para novo plano
  renderizarBeneficiosModal(['perfil_basico','exibir_precos','relatorio_cliques']);
  renderizarFeaturesModal([]);
  mpAtualizarPeriodo();
  document.getElementById('modal-plano').style.display = 'block';
}

function fecharModalPlano() {
  document.getElementById('modal-plano').style.display = 'none';
  _planoEditandoId = null;
}

// ─── Renderizar lista de features no modal ───────────────────────────────────
function renderizarFeaturesModal(features) {
  const list = document.getElementById('mp-features-list');
  if (!list) return;
  list.innerHTML = features.map((f, i) =>
    '<div style="display:flex;align-items:center;gap:8px;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.08);border-radius:9px;padding:8px 10px">'
    + '<label style="display:flex;align-items:center;gap:6px;cursor:pointer;flex:1;min-width:0">'
    +   '<input type="checkbox" data-fi="' + i + '" class="feat-check" style="accent-color:var(--laranja);width:16px;height:16px;flex-shrink:0"' + (f.incluido ? ' checked' : '') + '/>'
    +   '<input type="text" data-fi="' + i + '" class="feat-txt" value="' + f.texto.replace(/"/g, '&quot;') + '" style="flex:1;background:transparent;border:none;color:#fff;font-size:12px;outline:none;min-width:0"/>'
    + '</label>'
    + '<button data-fi="' + i + '" onclick="removerFeatureModal(parseInt(this.dataset.fi))" style="background:rgba(255,82,82,0.12);color:#FF5252;border:none;border-radius:6px;width:24px;height:24px;cursor:pointer;font-size:12px;flex-shrink:0">✕</button>'
    + '</div>'
  ).join('');
}

function adicionarFeatureModal() {
  const features = coletarFeaturesModal();
  features.push({ texto: 'Novo recurso', incluido: true });
  renderizarFeaturesModal(features);
  // Focar no último input adicionado
  const inputs = document.querySelectorAll('#mp-features-list .feat-txt');
  if (inputs.length) { inputs[inputs.length - 1].focus(); inputs[inputs.length - 1].select(); }
}

function removerFeatureModal(idx) {
  const features = coletarFeaturesModal();
  features.splice(idx, 1);
  renderizarFeaturesModal(features);
}

function coletarFeaturesModal() {
  const checks = document.querySelectorAll('#mp-features-list .feat-check');
  const texts  = document.querySelectorAll('#mp-features-list .feat-txt');
  const features = [];
  for (let i = 0; i < texts.length; i++) {
    features.push({ texto: texts[i].value.trim() || 'Recurso', incluido: checks[i].checked });
  }
  return features;
}

// ─── Salvar plano (criar ou editar) ─────────────────────────────────────────
async function salvarPlanoModal() {
  const nome = document.getElementById('mp-nome').value.trim();
  if (!nome) { alert('Informe o nome do plano.'); return; }
  const valorStr = document.getElementById('mp-valor').value;
  const valorCentavos = Math.round(parseFloat(valorStr || '0') * 100);
  const ciclo = document.getElementById('mp-ciclo').value;
  const body = {
    nome,
    emoji:     document.getElementById('mp-emoji').value.trim() || '📦',
    cor:       document.getElementById('mp-cor').value || '#FF6D00',
    valor:     valorCentavos,
    ciclo,
    descricao: document.getElementById('mp-descricao').value.trim(),
    ativo:     document.getElementById('mp-ativo').checked,
    destaque:  document.getElementById('mp-destaque').checked,
    diasTeste: (ciclo === 'trial' || ciclo === 'forever') ? parseInt(document.getElementById('mp-dias-teste')?.value || '0') : 0,
    beneficios: coletarBeneficiosModal(),
    features:  coletarFeaturesModal()
  };
  const btn = document.querySelector('#modal-plano button[onclick="salvarPlanoModal()"]');
  if (btn) { btn.disabled = true; btn.textContent = 'Salvando...'; }
  try {
    let res;
    if (_planoEditandoId) {
      res = await fetch('/api/admin/planos-posto/' + encodeURIComponent(_planoEditandoId) + '?key=' + encodeURIComponent(ADMIN_KEY), {
        method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body)
      });
    } else {
      // Gerar id a partir do nome
      body.id = 'posto_' + nome.toLowerCase().replace(/[^a-z0-9]/g, '_').replace(/_+/g, '_').replace(/^_|_$/g, '') + '_' + Date.now();
      res = await fetch('/api/admin/planos-posto?key=' + encodeURIComponent(ADMIN_KEY), {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body)
      });
    }
    const data = await res.json();
    if (!res.ok || data.erro) throw new Error(data.erro || 'Erro ao salvar');
    fecharModalPlano();
    await carregarEstatisticasPlanos();
    mostrarToastPostos('✅ Plano salvo com sucesso!', '#00C853');
  } catch(e) {
    alert('Erro ao salvar plano: ' + e.message);
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-save"></i> Salvar Plano'; }
  }
}

// ─── Deletar plano ───────────────────────────────────────────────────────────
async function deletarPlanoModal() {
  if (!_planoEditandoId) return;
  const p = _planosData.find(x => x.id === _planoEditandoId);
  if (!confirm('Excluir o plano "' + (p ? p.nome : _planoEditandoId) + '"? Esta ação não pode ser desfeita.')) return;
  try {
    const res = await fetch('/api/admin/planos-posto/' + encodeURIComponent(_planoEditandoId) + '?key=' + encodeURIComponent(ADMIN_KEY), {
      method: 'DELETE'
    });
    const data = await res.json();
    if (!res.ok || data.erro) throw new Error(data.erro || 'Erro ao excluir');
    fecharModalPlano();
    await carregarEstatisticasPlanos();
    mostrarToastPostos('🗑️ Plano excluído.', '#FF5252');
  } catch(e) {
    alert('Erro: ' + e.message);
  }
}

// ─── Toast helper ────────────────────────────────────────────────────────────
function _mostrarToast(msg, cor) {
  const t = document.createElement('div');
  t.textContent = msg;
  t.style.cssText = 'position:fixed;bottom:28px;left:50%;transform:translateX(-50%);background:' + cor + ';color:#fff;font-weight:700;font-size:13px;padding:12px 24px;border-radius:100px;z-index:99999;box-shadow:0 4px 20px rgba(0,0,0,0.4);pointer-events:none;transition:opacity 0.5s';
  document.body.appendChild(t);
  setTimeout(() => { t.style.opacity = '0'; setTimeout(() => t.remove(), 500); }, 2500);
}

async function carregarEstatisticasNiveis() {
  try {
    const [usRes, asRes] = await Promise.all([
      fetch('/api/admin/usuarios?key=' + encodeURIComponent(ADMIN_KEY)),
      fetch('/api/admin/assinaturas?key=' + encodeURIComponent(ADMIN_KEY))
    ]);
    const usData = await usRes.json();
    const asData = await asRes.json();
    const usuarios = usData.usuarios || [];
    const assinaturas = asData.assinaturas || [];
    const assinAtivas = assinaturas.filter(a => a.status === 'ACTIVE').length;
    const bloqueados = usuarios.filter(u => u.bloqueado).length;
    const free = usuarios.length - assinAtivas - bloqueados;
    const nc = (id, v) => { const el = document.getElementById(id); if(el) el.textContent = v; };
    nc('nivel-admin-count', '1'); // você é o admin
    nc('nivel-premium-count', assinAtivas);
    nc('nivel-free-count', Math.max(0, free));
    nc('nivel-bloqueado-count', bloqueados);
  } catch(e) { console.warn('carregarEstatisticasNiveis:', e); }
}

// ── MENU DO APP ──────────────────────────────────────────────────────────────
const MENU_APP_ITENS_PADRAO = [
  { id: 'minhaConta',      label: 'Minha conta',         icone: '👤', ativo: true },
  { id: 'meusVeiculos',    label: 'Meus veículos',        icone: '🚗', ativo: true },
  { id: 'assinatura',      label: 'Assinatura',           icone: '💳', ativo: true },
  { id: 'formasPagamento', label: 'Formas de pagamento',  icone: '💰', ativo: true },
  { id: 'notificacoes',    label: 'Notificações',         icone: '🔔', ativo: true },
  { id: 'pontosNiveis',    label: 'Pontos & Níveis',      icone: '⭐', ativo: true },
  { id: 'indiqueGanhe',    label: 'Indique e ganhe',      icone: '🎁', ativo: true },
  { id: 'ajudaSuporte',    label: 'Ajuda e suporte',      icone: '❓', ativo: true },
  { id: 'configuracoes',   label: 'Configurações',        icone: '⚙️', ativo: true },
];

let _menuAppItens = [];

async function carregarMenuApp() {
  const el = document.getElementById('menu-app-itens');
  if (!el) return;
  try {
    const res = await fetch('/api/admin/menu-app?key=' + encodeURIComponent(ADMIN_KEY));
    const data = await res.json();
    _menuAppItens = data.itens || MENU_APP_ITENS_PADRAO;
    renderMenuAppItens(_menuAppItens);
  } catch(e) {
    _menuAppItens = MENU_APP_ITENS_PADRAO;
    renderMenuAppItens(_menuAppItens);
  }
}

function renderMenuAppItens(itens) {
  var el = document.getElementById('menu-app-itens');
  if (!el) return;
  el.innerHTML = itens.map(function(item) {
    var a = item.ativo;
    var id = item.id;
    var borderOpacity = a ? '0.12' : '0.05';
    var opacity = a ? '1' : '0.35';
    var labelColor = a ? '#fff' : 'rgba(255,255,255,0.35)';
    var statusColor = a ? '#FF6D00' : 'rgba(255,255,255,0.25)';
    var statusText = a ? 'Visivel' : 'Oculto';
    var trackBg = a ? '#FF6D00' : 'rgba(255,255,255,0.1)';
    var knobLeft = a ? '23px' : '3px';
    return '<div style="display:flex;align-items:center;justify-content:space-between;background:#0A1520;border-radius:12px;padding:14px 18px;border:1px solid rgba(255,255,255,' + borderOpacity + ');transition:border-color 0.2s" id="menu-row-' + id + '">'
      + '<div style="display:flex;align-items:center;gap:12px">'
      +   '<span style="font-size:22px;opacity:' + opacity + ';transition:opacity 0.2s" id="menu-icone-' + id + '">' + item.icone + '</span>'
      +   '<div>'
      +     '<div style="font-size:14px;font-weight:700;color:' + labelColor + ';transition:color 0.2s" id="menu-label-' + id + '">' + item.label + '</div>'
      +     '<div style="font-size:11px;color:rgba(255,255,255,0.25);margin-top:2px">ID: ' + id + '</div>'
      +   '</div>'
      + '</div>'
      + '<div style="display:flex;align-items:center;gap:10px">'
      +   '<span style="font-size:11px;font-weight:700;color:' + statusColor + ';min-width:40px;text-align:right;transition:color 0.2s" id="menu-status-' + id + '">' + statusText + '</span>'
      +   '<div onclick="toggleMenuitem(&apos;' + id + '&apos;)" id="menu-track-' + id + '"'
      +     ' style="position:relative;width:46px;height:26px;border-radius:13px;background:' + trackBg + ';cursor:pointer;transition:background 0.25s;flex-shrink:0">'
      +     '<div id="menu-knob-' + id + '"'
      +       ' style="position:absolute;top:3px;left:' + knobLeft + ';width:20px;height:20px;border-radius:50%;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,0.4);transition:left 0.25s;pointer-events:none"></div>'
      +   '</div>'
      + '</div>'
      + '</div>';
  }).join('');
}

function toggleMenuitem(id) {
  const track  = document.getElementById('menu-track-' + id);
  const knob   = document.getElementById('menu-knob-' + id);
  const status = document.getElementById('menu-status-' + id);
  const label  = document.getElementById('menu-label-' + id);
  const icone  = document.getElementById('menu-icone-' + id);
  const row    = document.getElementById('menu-row-' + id);
  if (!track) return;
  const ativo = track.dataset.ativo !== 'false' && knob.style.left !== '3px';
  const novoAtivo = !ativo;
  // Atualiza visual
  track.style.background    = novoAtivo ? '#FF6D00' : 'rgba(255,255,255,0.1)';
  knob.style.left           = novoAtivo ? '23px' : '3px';
  status.textContent        = novoAtivo ? 'Visível' : 'Oculto';
  status.style.color        = novoAtivo ? '#FF6D00' : 'rgba(255,255,255,0.25)';
  label.style.color         = novoAtivo ? '#fff' : 'rgba(255,255,255,0.35)';
  icone.style.opacity       = novoAtivo ? '1' : '0.35';
  row.style.borderColor     = novoAtivo ? 'rgba(255,255,255,0.12)' : 'rgba(255,255,255,0.05)';
  // Salva estado no input hidden para o salvarMenuApp ler
  let inp = document.getElementById('menu-toggle-' + id);
  if (!inp) {
    inp = document.createElement('input');
    inp.type = 'checkbox';
    inp.id   = 'menu-toggle-' + id;
    inp.style.display = 'none';
    document.body.appendChild(inp);
  }
  inp.checked = novoAtivo;
}

async function salvarMenuApp() {
  const base = _menuAppItens.length ? _menuAppItens : MENU_APP_ITENS_PADRAO;
  const itens = base.map(item => {
    const knob = document.getElementById('menu-knob-' + item.id);
    // knob em left:23px = ativo, left:3px = inativo
    const ativo = knob ? knob.style.left === '23px' : item.ativo;
    return { ...item, ativo };
  });
  const btn = document.querySelector('#section-menu-app .btn-refresh');
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Salvando...'; }
  try {
    const res = await fetch('/api/admin/menu-app', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ key: ADMIN_KEY, itens })
    });
    const data = await res.json();
    if (data.ok) {
      _menuAppItens = itens;
      showToast('✅ Menu salvo com sucesso!', 'ok');
    } else {
      showToast('❌ Erro ao salvar: ' + (data.error || ''), 'err');
    }
  } catch(e) {
    showToast('❌ Erro de conexão', 'err');
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-save"></i> Salvar'; }
  }
}

// ══════════════════════════════════════════════════════════════════════════════
//  EQUIPE & ACESSOS — JavaScript do Painel Admin
// ══════════════════════════════════════════════════════════════════════════════

const MODULOS_PERM = [
  { key: 'dashboard',    label: 'Dashboard',        desc: 'Visão geral e KPIs' },
  { key: 'usuarios',     label: 'Usuários do App',   desc: 'Gerenciar usuários' },
  { key: 'dados',        label: 'Dados & Contatos',  desc: 'Formulários e dados' },
  { key: 'assinaturas',  label: 'Assinaturas',       desc: 'Planos e pagamentos' },
  { key: 'planos',       label: 'Planos & Produtos', desc: 'Planos app e postos' },
  { key: 'menuApp',      label: 'Menu do App',       desc: 'Configurar menu' },
  { key: 'postos',       label: 'Postos & Dados',    desc: 'Postos e parceiros' },
  { key: 'precos',       label: 'Preços Reportados', desc: 'Preços colaborativos' },
  { key: 'mapa',         label: 'Mapa ao Vivo',      desc: 'Mapa de postos' },
];

let _staffEditando = null;
let _staffRedefinindoEmail = null;
let _staffLista = [];

async function carregarEquipe() {
  document.getElementById('equipe-loading').style.display = 'block';
  document.getElementById('equipe-vazia').style.display = 'none';
  document.getElementById('equipe-tabela').style.display = 'none';
  try {
    const res = await fetch('/api/admin/equipe?key=' + encodeURIComponent(ADMIN_KEY));
    if (!res.ok) { showToast('Erro ao carregar equipe (' + res.status + ')', 'err'); return; }
    const data = await res.json();
    _staffLista = data.staff || [];
    renderEquipeTabela(_staffLista);
  } catch(e) {
    showToast('Erro de conexão ao carregar equipe', 'err');
  } finally {
    document.getElementById('equipe-loading').style.display = 'none';
  }
}

// Helper: escapa email/nome para uso seguro em data-attributes HTML
function _esc(v) { return String(v || '').replace(/&/g,'&amp;').replace(/"/g,'&quot;'); }

function renderEquipeTabela(lista) {
  const masters = lista.filter(s => s.role === 'master').length;
  const admins  = lista.filter(s => s.role === 'admin').length;
  const funcs   = lista.filter(s => s.role === 'funcionario').length;
  const cm = document.getElementById('eq-count-master'); if(cm) cm.textContent = masters;
  const ca = document.getElementById('eq-count-admin');  if(ca) ca.textContent = admins;
  const cf = document.getElementById('eq-count-func');   if(cf) cf.textContent = funcs;

  if (!lista.length) {
    document.getElementById('equipe-vazia').style.display = 'block';
    document.getElementById('equipe-tabela').style.display = 'none';
    return;
  }
  document.getElementById('equipe-vazia').style.display = 'none';
  document.getElementById('equipe-tabela').style.display = 'table';

  const tbody = document.getElementById('equipe-tbody');
  tbody.innerHTML = lista.map(s => {
    const emailEsc = _esc(s.email);
    const nomeEsc  = _esc(s.nome);
    const roleBadge = s.role === 'master'
      ? '<span class="role-badge-master"><i class="fas fa-crown"></i>Master</span>'
      : s.role === 'admin'
        ? '<span class="role-badge-admin"><i class="fas fa-user-shield"></i>Admin</span>'
        : '<span class="role-badge-funcionario"><i class="fas fa-user-tie"></i>Funcionario</span>';

    // Contar permissões habilitadas
    const perm = s.permissoes || {};
    const totalPerm = MODULOS_PERM.length;
    const habPerm = s.role === 'master' ? totalPerm : Object.values(perm).filter(Boolean).length;
    const permStr = s.role === 'master'
      ? '<span style="color:#FFD600;font-size:11px;font-weight:700">Todos os modulos</span>'
      : '<span style="font-size:11px;font-weight:700;color:rgba(255,255,255,0.5)">' + habPerm + '/' + totalPerm + ' modulos</span>';

    // Usar data-attributes para passar parâmetros — evita problema de aspas aninhadas
    const novoAtivo = s.ativo ? 'false' : 'true';
    const statusClass = s.ativo ? 'staff-ativo-toggle staff-ativo-on' : 'staff-ativo-toggle staff-ativo-off';
    const statusIcon  = s.ativo ? 'fa-check-circle' : 'fa-times-circle';
    const statusText  = s.ativo ? 'Ativo' : 'Inativo';
    const statusBadge = '<span class="' + statusClass + '" data-email="' + emailEsc + '" data-ativo="' + novoAtivo + '" onclick="toggleStaffAtivoEl(this)"><i class="fas ' + statusIcon + '"></i>' + statusText + '</span>';

    const criadoEm = s.criadoEm ? new Date(s.criadoEm).toLocaleDateString('pt-BR') : '-';

    return '<tr class="tr-hover">'
      + '<td><div style="font-weight:700;color:#fff">' + (nomeEsc || '-') + '</div>'
        + (s.cargo ? '<div style="font-size:10px;color:rgba(255,255,255,0.3);margin-top:2px">' + _esc(s.cargo) + '</div>' : '') + '</td>'
      + '<td style="font-family:monospace;font-size:11px;color:rgba(255,255,255,0.6)">' + emailEsc + '</td>'
      + '<td>' + roleBadge + '</td>'
      + '<td>' + permStr + '</td>'
      + '<td>' + statusBadge + '</td>'
      + '<td style="font-size:11px;color:rgba(255,255,255,0.35)">' + criadoEm + '</td>'
      + '<td style="text-align:right">'
        + '<button class="btn-info" style="padding:5px 10px;font-size:10px;margin-right:4px" data-email="' + emailEsc + '" onclick="abrirModalEditarStaffEl(this)"><i class="fas fa-edit"></i> Editar</button>'
        + '<button class="btn-danger" style="padding:5px 10px;font-size:10px;margin-right:4px" data-email="' + emailEsc + '" data-nome="' + nomeEsc + '" onclick="abrirModalSenhaStaffEl(this)"><i class="fas fa-key"></i></button>'
        + '<button class="btn-danger" style="padding:5px 10px;font-size:10px" data-email="' + emailEsc + '" data-nome="' + nomeEsc + '" onclick="excluirStaffEl(this)"><i class="fas fa-trash"></i></button>'
      + '</td>'
    + '</tr>';
  }).join('');
}

// Wrappers que leem data-attributes em vez de receber parâmetros direto no onclick
function toggleStaffAtivoEl(el) { toggleStaffAtivo(el.dataset.email, el.dataset.ativo === 'true'); }
function abrirModalEditarStaffEl(el) { abrirModalEditarStaff(el.dataset.email); }
function abrirModalSenhaStaffEl(el) { abrirModalSenhaStaff(el.dataset.email, el.dataset.nome); }
function excluirStaffEl(el) { excluirStaff(el.dataset.email, el.dataset.nome); }

function buildPermRows(permissoes, role) {
  const wrap = document.getElementById('perm-rows');
  if (!wrap) return;
  wrap.innerHTML = MODULOS_PERM.map(m => {
    const checked = role === 'master' ? true : !!(permissoes && permissoes[m.key]);
    const disabled = role === 'master' ? 'disabled' : '';
    return '<div class="perm-row">'
      + '<div class="perm-label">' + m.label + '<small>' + m.desc + '</small></div>'
      + '<div class="perm-check"><input type="checkbox" id="perm-' + m.key + '" ' + (checked ? 'checked' : '') + ' ' + disabled + '/></div>'
      + '<div></div>'
    + '</div>';
  }).join('');
}

function selectRole(role) {
  document.querySelectorAll('.role-opt').forEach(el => {
    el.classList.remove('selected-master','selected-admin','selected-funcionario');
  });
  const sel = document.querySelector('.role-opt[data-role="' + role + '"]');
  if (sel) sel.classList.add('selected-' + role);
  const radios = document.querySelectorAll('input[name="staff-role"]');
  radios.forEach(r => { r.checked = r.value === role; });
  const permWrap = document.getElementById('staff-perm-wrap');
  if (permWrap) permWrap.style.display = (role === 'master') ? 'none' : 'block';
  // rebuild perm rows com estado atual
  const currentPerm = getPermAtual();
  buildPermRows(currentPerm, role);
}

function getPermAtual() {
  const perm = {};
  MODULOS_PERM.forEach(m => {
    const el = document.getElementById('perm-' + m.key);
    perm[m.key] = el ? el.checked : false;
  });
  return perm;
}

function marcarTodasPermissoes(val) {
  MODULOS_PERM.forEach(m => {
    const el = document.getElementById('perm-' + m.key);
    if (el && !el.disabled) el.checked = val;
  });
}

function abrirModalNovoStaff() {
  _staffEditando = null;
  document.getElementById('modal-staff-titulo').textContent = '👤 Novo Funcionário';
  document.getElementById('staff-edit-email').value = '';
  document.getElementById('staff-nome').value = '';
  document.getElementById('staff-cargo').value = '';
  document.getElementById('staff-email-input').value = '';
  document.getElementById('staff-email-input').readOnly = false;
  document.getElementById('staff-senha').value = '';
  document.getElementById('staff-ativo').checked = true;
  const senhaHint = document.getElementById('staff-senha-hint');
  if (senhaHint) senhaHint.style.display = 'none';
  const modalErr = document.getElementById('staff-modal-err');
  if (modalErr) modalErr.style.display = 'none';
  // reset role
  selectRole('funcionario');
  // permissões default = todas desmarcadas
  buildPermRows({}, 'funcionario');
  document.getElementById('modal-staff').style.display = 'flex';
}

function abrirModalEditarStaff(email) {
  const s = _staffLista.find(x => x.email === email);
  if (!s) return;
  _staffEditando = email;
  document.getElementById('modal-staff-titulo').textContent = '✏️ Editar Funcionário';
  document.getElementById('staff-edit-email').value = email;
  document.getElementById('staff-nome').value = s.nome || '';
  document.getElementById('staff-cargo').value = s.cargo || '';
  document.getElementById('staff-email-input').value = email;
  document.getElementById('staff-email-input').readOnly = true;
  document.getElementById('staff-senha').value = '';
  document.getElementById('staff-ativo').checked = !!s.ativo;
  const senhaHint = document.getElementById('staff-senha-hint');
  if (senhaHint) senhaHint.style.display = 'inline';
  const modalErr = document.getElementById('staff-modal-err');
  if (modalErr) modalErr.style.display = 'none';
  selectRole(s.role || 'funcionario');
  buildPermRows(s.permissoes || {}, s.role || 'funcionario');
  document.getElementById('modal-staff').style.display = 'flex';
}

function fecharModalStaff() {
  document.getElementById('modal-staff').style.display = 'none';
  _staffEditando = null;
}

async function salvarStaff() {
  const nome  = document.getElementById('staff-nome').value.trim();
  const cargo = document.getElementById('staff-cargo').value.trim();
  const email = document.getElementById('staff-email-input').value.trim().toLowerCase();
  const senha = document.getElementById('staff-senha').value;
  const ativo = document.getElementById('staff-ativo').checked;
  const roleEl = document.querySelector('input[name="staff-role"]:checked');
  const role = roleEl ? roleEl.value : 'funcionario';
  const modalErr = document.getElementById('staff-modal-err');
  modalErr.style.display = 'none';

  if (!nome) { modalErr.textContent = 'Nome é obrigatório.'; modalErr.style.display = 'block'; return; }
  if (!email || !email.includes('@')) { modalErr.textContent = 'E-mail inválido.'; modalErr.style.display = 'block'; return; }
  if (!_staffEditando && senha.length < 6) { modalErr.textContent = 'Senha deve ter mínimo 6 caracteres.'; modalErr.style.display = 'block'; return; }
  if (_staffEditando && senha && senha.length < 6) { modalErr.textContent = 'Nova senha deve ter mínimo 6 caracteres.'; modalErr.style.display = 'block'; return; }

  const permissoes = {};
  MODULOS_PERM.forEach(m => {
    const el = document.getElementById('perm-' + m.key);
    permissoes[m.key] = el ? el.checked : false;
  });

  const payload = { email, nome, cargo, role, ativo, permissoes, key: ADMIN_KEY };
  if (!_staffEditando || senha) payload.senha = senha;

  const btn = document.getElementById('btn-salvar-staff');
  btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Salvando...';

  try {
    const res = await fetch('/api/admin/equipe', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    const data = await res.json();
    if (data.ok) {
      showToast(_staffEditando ? '✅ Funcionário atualizado!' : '✅ Funcionário criado!', 'ok');
      fecharModalStaff();
      carregarEquipe();
    } else {
      modalErr.textContent = data.erro || 'Erro ao salvar.';
      modalErr.style.display = 'block';
    }
  } catch(e) {
    modalErr.textContent = 'Erro de conexão.';
    modalErr.style.display = 'block';
  } finally {
    btn.disabled = false; btn.innerHTML = '<i class="fas fa-save"></i> Salvar';
  }
}

async function excluirStaff(email, nome) {
  if (!confirm('Excluir o funcionario "' + nome + '" (' + email + ')? Esta acao nao pode ser desfeita.')) return;
  try {
    const res = await fetch('/api/admin/equipe/' + encodeURIComponent(email) + '?key=' + encodeURIComponent(ADMIN_KEY), { method: 'DELETE' });
    const data = await res.json();
    if (data.ok) { showToast('✅ Funcionário removido.', 'ok'); carregarEquipe(); }
    else showToast('❌ ' + (data.erro || 'Erro ao excluir'), 'err');
  } catch(e) { showToast('❌ Erro de conexão', 'err'); }
}

async function toggleStaffAtivo(email, novoAtivo) {
  const s = _staffLista.find(x => x.email === email);
  if (!s) return;
  const payload = {
    email, nome: s.nome, cargo: s.cargo || '', role: s.role,
    ativo: novoAtivo, permissoes: s.permissoes || {}, key: ADMIN_KEY
  };
  try {
    const res = await fetch('/api/admin/equipe', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    const data = await res.json();
    if (data.ok) { showToast(novoAtivo ? '✅ Conta ativada' : '⛔ Conta desativada', 'ok'); carregarEquipe(); }
    else showToast('❌ Erro ao atualizar status', 'err');
  } catch(e) { showToast('❌ Erro de conexão', 'err'); }
}

function abrirModalSenhaStaff(email, nome) {
  _staffRedefinindoEmail = email;
  document.getElementById('modal-staff-senha-desc').textContent = 'Redefinir senha de: ' + nome + ' (' + email + ')';
  document.getElementById('nova-senha-input').value = '';
  document.getElementById('modal-staff-senha').style.display = 'flex';
}

async function confirmarRedefinirSenha() {
  const novaSenha = document.getElementById('nova-senha-input').value;
  if (!novaSenha || novaSenha.length < 6) { showToast('Senha deve ter mínimo 6 caracteres', 'err'); return; }
  try {
    const res = await fetch('/api/admin/equipe/' + encodeURIComponent(_staffRedefinindoEmail) + '/senha?key=' + encodeURIComponent(ADMIN_KEY), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ novaSenha })
    });
    const data = await res.json();
    if (data.ok) {
      showToast('✅ Senha redefinida com sucesso!', 'ok');
      document.getElementById('modal-staff-senha').style.display = 'none';
    } else {
      showToast('❌ ' + (data.erro || 'Erro ao redefinir senha'), 'err');
    }
  } catch(e) { showToast('❌ Erro de conexão', 'err'); }
}
